    const y2 = 200 + Math.sin(angle + Math.PI/3) * 120;
    const x3 = 200 + Math.cos(angle - Math.PI/3) * 120;
    const y3 = 200 + Math.sin(angle - Math.PI/3) * 120;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x3, y3);
    ctx.closePath();
    ctx.fill();
}

// Draw hexagons
