ctx.fillStyle = C2; ctx.fillRect(0, 0, W, 200);
ctx.fillStyle = C3; ctx.fillRect(0, 200, W, 200);

// Draw spiral
let x = 200, y = 200, r = 0, angle = 0, dir = 1;
const MAX_R = 180;

while (r < MAX_R) {
    r += 5 * dir;
    angle += 0.5 * dir;

    const cx = x + Math.cos(angle) * r;
    const cy = y - Math.sin(angle) * r;

    if (dir === 1) {
        ctx.fillStyle = C5; // Highlight
        ctx.fillRect(Math.round(cx), Math.round(cy), 2, 2);
        ctx.fillStyle = C4; // Shadow
        ctx.fillRect(Math.round(cx), Math.round(cy), 2, 2);
    } else {
        ctx.fillStyle = C6; // Background
        ctx.fillRect(Math.round(cx), Math.round(cy), 2, 2);
    }
}

